window.products.push({"id":1172693,"name":"SyncStop","category":"electronics","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41dgCDEDBnL._AC_SL1024_.jpg","description":"SyncStop prevents accidental data exchange when your device is plugged into someone else’s computer or a public charging station. SyncStop achieves this by blocking the data pins on any USB cable and allowing only power to flow through. This minimizes opportunities to steal your data or install malware on your mobile device. Works with any mobile device. SyncStop is the 'cased' version of the Original USB Condom. The Original USB Condom is also available on Amazon.","images":["https://m.media-amazon.com/images/I/41dgCDEDBnL._AC_SL1024_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Syncstop","source_asin":"B00ZQAY23U","category_path":"Electronics"},"sku":"BM-1172693","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00ZQAY23U","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B00ZQAY23U","price_pending":true,"merchant_ready":false});
